// ---- events (merc-live) ----
export interface AlertCreatedPayload {
  alert: AlertCard;
}

export interface ApprovalCreatedPayload {
  approval: ApprovalCard;
}

export interface ApprovalDecidedPayload {
  approval: ApprovalCard;
}

export interface BriefingReadyPayload {
  briefing_id: string;
  date: string;
}

export interface BuddyCallStatusPayload {
  buddy_call_id: string;
  channel: "call" | "whatsapp";
  status: string;
}

export interface CandidatesReadyPayload {
  search_id: string;
  found: number;
  duplicates: number;
  scored: number;
}

export interface DebriefConfirmationStatusPayload {
  debrief_confirmation_id: string;
  voice_log_id: string;
  status: string;
}

export interface ManagerCallStatusPayload {
  approval_id: string;
  outcome: "queued" | "ringing" | "answered" | "no_answer" | "busy" | "voicemail" | "failed";
}

export interface PlanProposedPayload {
  plan_id: string;
  week_start: string;
}

export interface ResultCardReadyPayload {
  voice_log_id: string;
  result: ResultCard;
}

export interface VisitBriefReadyPayload {
  visit_brief_id: string;
  visit_id: string;
  account: AccountRef;
}

export interface VoiceLogStatusPayload {
  voice_log_id: string;
  status: string;
  error?: string | null;
}

export type EventType =
  | "alert.created"
  | "approval.created"
  | "approval.decided"
  | "briefing.ready"
  | "buddy_call.status"
  | "candidates.ready"
  | "debrief_confirmation.status"
  | "manager_call.status"
  | "plan.proposed"
  | "result_card.ready"
  | "visit_brief.ready"
  | "voice_log.status";

export interface EventPayloadMap {
  "alert.created": AlertCreatedPayload;
  "approval.created": ApprovalCreatedPayload;
  "approval.decided": ApprovalDecidedPayload;
  "briefing.ready": BriefingReadyPayload;
  "buddy_call.status": BuddyCallStatusPayload;
  "candidates.ready": CandidatesReadyPayload;
  "debrief_confirmation.status": DebriefConfirmationStatusPayload;
  "manager_call.status": ManagerCallStatusPayload;
  "plan.proposed": PlanProposedPayload;
  "result_card.ready": ResultCardReadyPayload;
  "visit_brief.ready": VisitBriefReadyPayload;
  "voice_log.status": VoiceLogStatusPayload;
}

/** WebSocket envelope: {type, at, payload}. */
export interface MercEvent<T extends EventType = EventType> {
  type: T;
  at: string;
  payload: EventPayloadMap[T];
}

